mapper.select:
SELECT COUNT(1)
FROM exp_org_unit
WHERE org_code = #{orgCode}

    AND org_id != #{excludeOrgId}

SELECT o.org_id, o.parent_org_id, o.org_code, o.org_name, o.org_type, o.org_path, o.org_level, o.manager_person_id, o.contact_phone, o.address, o.status, o.sort_no, o.created_time, o.updated_time, o.remark, p.person_name as manager_name, creator.account_display as created_name FROM exp_org_unit o LEFT JOIN exp_person p ON o.manager_person_id = p.person_id LEFT JOIN exp_account creator ON o.created_by = creator.account_id WHERE o.org_id IN
#{orgId}
ORDER BY o.sort_no ASC, o.created_time DESC
